import sys

def main():
    import sys
    n, k = map(int, sys.stdin.read().strip().split())
    if k > n * n:
        print(-1)
        return
    matrix = [[0] * n for _ in range(n)]
    count = 0
    for i in range(n):
        for j in range(i + 1):
            if count < k:
                matrix[i][j] = 1
                matrix[j][i] = 1
                count += 2 if i != j else 1
    if count > k:
        matrix[n - 1][n - 1] = 0
        count -= 1
    if count < k:
        print(-1)
    else:
        for row in matrix:
            print(' '.join(map(str, row)))

main()
